import collections
def solve(g):
    h,w=len(g),len(g[0]); out=[r[:] for r in g]
    bg=collections.Counter(x for r in g for x in r).most_common(1)[0][0]
    obj=Counter(x for r in g for x in r).most_common(2)[1][0] if len(g)>1 else None
    # flood fill outside
    seen=set(); q=collections.deque()
    for i in range(h):
        for j in [0,w-1]:
            if g[i][j]==bg and (i,j) not in seen: seen.add((i,j)); q.append((i,j))
    for j in range(w):
        for i in [0,h-1]:
            if g[i][j]==bg and (i,j) not in seen: seen.add((i,j)); q.append((i,j))
    while q:
        i,j=q.popleft()
        for di_,dj_ in ((1,0),(-1,0),(0,1),(0,-1)):
            a,b=i+di_,j+dj_
            if 0<=a<h and 0<=b<w and (a,b) not in seen and g[a][b]==bg:
                seen.add((a,b)); q.append((a,b))
    # cells not reached and bg -> hole
    for (i,j) in [(x,y) for x in range(h) for y in range(w) if g[x][y]==bg and (x,y) not in seen]:
        out[i][j]=4
    return out
